<template>
  <div class="page">
    <v-card flat class="hero pa-5 mb-4"><div class="d-flex flex-wrap align-center"><div><div class="text-overline">FINANCE</div><h1 class="text-h5 font-weight-bold">Installments</h1><div class="grey--text">Monitor due dates, balances and collect payments against individual installments.</div></div><v-spacer/><v-btn text color="#165134" @click="load"><v-icon left>mdi-refresh</v-icon>Refresh</v-btn></div></v-card>
    <v-row class="mb-1">
      <v-col cols="6" md="3"><v-card flat class="summary-card pa-4" @click="setStatus(null)"><div class="caption grey--text">Installments Shown</div><div class="text-h6 font-weight-bold">{{items.length}}</div></v-card></v-col>
      <v-col cols="6" md="3"><v-card flat class="summary-card pa-4" @click="setStatus('overdue')"><div class="caption grey--text">Overdue Shown</div><div class="text-h6 font-weight-bold error--text">{{overdueCount}}</div></v-card></v-col>
      <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Outstanding Shown</div><div class="text-h6 font-weight-bold">PKR {{money(outstandingShown)}}</div></v-card></v-col>
      <v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Overdue Amount Shown</div><div class="text-h6 font-weight-bold error--text">PKR {{money(overdueAmount)}}</div></v-card></v-col>
    </v-row>
    <v-card flat class="filter-card mb-4"><v-card-text><v-row dense align="center"><v-col cols="12" md="4"><v-select v-model="status" :items="statuses" outlined dense hide-details clearable label="Status" @change="load"/></v-col><v-col cols="12" md="3"><v-text-field v-model="from" outlined dense hide-details type="date" label="Due from" @change="load"/></v-col><v-col cols="12" md="3"><v-text-field v-model="to" outlined dense hide-details type="date" label="Due to" @change="load"/></v-col><v-col cols="12" md="2" class="text-md-right"><v-btn text color="grey darken-1" @click="clearFilters"><v-icon left>mdi-filter-remove</v-icon>Clear</v-btn></v-col></v-row></v-card-text></v-card>
    <v-card flat class="table-card"><v-data-table :headers="headers" :items="items" :items-per-page="15"><template v-slot:item.due_date="{item}"><div :class="{'error--text font-weight-bold':isOverdue(item)}">{{dateOnly(item.due_date)}}</div><div v-if="isOverdue(item)" class="caption error--text">{{daysOverdue(item)}} day(s) overdue</div></template><template v-slot:item.amount="{item}">{{ money(item.amount) }}</template><template v-slot:item.paid_amount="{item}">{{ money(item.paid_amount) }}</template><template v-slot:item.remaining_amount="{item}"><span :class="{'error--text':Number(item.remaining_amount)>0}">{{ money(item.remaining_amount) }}</span></template><template v-slot:item.status="{item}"><v-chip x-small :color="statusColor(displayStatus(item))" :outlined="displayStatus(item)==='partial'" dark>{{ displayStatus(item) }}</v-chip></template><template v-slot:item.actions="{item}"><v-btn v-if="$can('payments.create') && Number(item.remaining_amount)>0" small color="#165134" dark @click="openPayment(item)"><v-icon left small>mdi-cash-plus</v-icon>Pay</v-btn><v-btn v-if="$can('installments.view')" icon small class="ml-1" title="View installment" @click="view(item)"><v-icon small>mdi-eye</v-icon></v-btn><v-badge v-if="$can('installments.view')" :content="item.financial_documents_count" :value="item.financial_documents_count" color="#165134" overlap><v-btn icon small color="blue-grey" title="Receipts / invoices / documents" @click="openDocuments(item)"><v-icon small>mdi-paperclip</v-icon></v-btn></v-badge></template><template v-slot:no-data><div class="pa-8 grey--text">No installments found for the selected filters.</div></template></v-data-table></v-card>
    <v-dialog v-model="paymentDialog" max-width="620" persistent><v-card><v-card-title>Record Installment Payment<v-spacer/><v-btn icon @click="paymentDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text v-if="selected"><v-alert type="info" text dense class="mb-4">Installment #{{ selected.installment_number }} — Remaining: <strong>{{ money(selected.remaining_amount) }}</strong></v-alert><v-row dense><v-col cols="12" md="6"><v-text-field v-model="payment.amount" type="number" min="0.01" :max="selected.remaining_amount" step="0.01" outlined dense label="Amount *"/></v-col><v-col cols="12" md="6"><v-select v-model="payment.payment_method" :items="methods" outlined dense label="Payment Method *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="payment.payment_date" type="date" outlined dense label="Payment Date *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="payment.reference_number" outlined dense label="Reference #"/></v-col><v-col cols="12" md="6"><v-text-field v-model="payment.bank_name" outlined dense label="Bank Name"/></v-col><v-col cols="12" md="6"><v-text-field v-model="payment.cheque_number" outlined dense label="Cheque #"/></v-col><v-col cols="12"><v-textarea v-model="payment.notes" outlined dense rows="2" label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="paymentDialog=false">Cancel</v-btn><v-btn v-if="$can('payments.create')" color="#165134" dark @click="savePayment">Save Payment</v-btn></v-card-actions></v-card></v-dialog>
    <financial-documents-dialog v-model="documentsDialog" entity-type="installment" :entity-id="documentEntity ? documentEntity.id : null" :title="documentEntity ? 'Installment Documents — #'+documentEntity.installment_number : 'Installment Documents'" :can-upload="$can('installments.create') || $can('installments.edit')" :can-delete="$can('installments.edit') || $can('installments.delete')" @updated="load"/>

    <v-dialog v-model="detailsDialog" max-width="600"><v-card><v-card-title>Installment Details<v-spacer/><v-btn icon @click="detailsDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text v-if="details"><v-list dense><v-list-item><v-list-item-content>Customer</v-list-item-content><v-list-item-content class="text-right">{{ customerName(details) }}</v-list-item-content></v-list-item><v-list-item><v-list-item-content>Booking</v-list-item-content><v-list-item-content class="text-right">{{ bookingNumber(details) }}</v-list-item-content></v-list-item><v-list-item><v-list-item-content>Plan</v-list-item-content><v-list-item-content class="text-right">{{ planName(details) }}</v-list-item-content></v-list-item><v-divider/><v-list-item><v-list-item-content>Amount</v-list-item-content><v-list-item-content class="text-right font-weight-bold">{{ money(details.amount) }}</v-list-item-content></v-list-item><v-list-item><v-list-item-content>Paid</v-list-item-content><v-list-item-content class="text-right">{{ money(details.paid_amount) }}</v-list-item-content></v-list-item><v-list-item><v-list-item-content>Remaining</v-list-item-content><v-list-item-content class="text-right error--text">{{ money(details.remaining_amount) }}</v-list-item-content></v-list-item></v-list></v-card-text></v-card></v-dialog>
  </div>
</template>
<script>
import api from '../../../services/api'
import FinancialDocumentsDialog from '../../../components/FinancialDocumentsDialog.vue'
export default {name:'Installments',components:{FinancialDocumentsDialog},data(){return{loading:false,saving:false,items:[],status:null,from:null,to:null,selected:null,details:null,paymentDialog:false,detailsDialog:false,documentsDialog:false,documentEntity:null,statuses:['pending','partial','paid','overdue'],methods:['cash','bank_transfer','cheque','online','other'],headers:[{text:'#',value:'installment_number'},{text:'Customer',value:'booking.customer.name'},{text:'Booking',value:'booking.booking_number'},{text:'Due Date',value:'due_date'},{text:'Amount',value:'amount'},{text:'Paid',value:'paid_amount'},{text:'Remaining',value:'remaining_amount'},{text:'Status',value:'status'},{text:'Actions',value:'actions',sortable:false}],payment:{amount:null,payment_method:'cash',payment_date:new Date().toISOString().slice(0,10),reference_number:'',bank_name:'',cheque_number:'',notes:''}}},computed:{overdueCount(){return this.items.filter(this.isOverdue).length},outstandingShown(){return this.items.reduce(function(n,x){return n+Number(x.remaining_amount||0)},0)},overdueAmount(){return this.items.filter(this.isOverdue).reduce(function(n,x){return n+Number(x.remaining_amount||0)},0)}},mounted(){this.applyRouteFilters();this.load()},watch:{'$route.query':{deep:true,handler(){this.applyRouteFilters();this.load()}}},methods:{applyRouteFilters(){this.status=this.$route.query.status||null;this.from=this.$route.query.from||null;this.to=this.$route.query.to||null},setStatus(status){this.status=status;this.load()},clearFilters(){this.status=null;this.from=null;this.to=null;this.load()},dateOnly(v){return v?String(v).slice(0,10):'—'},isOverdue(item){if(!item||Number(item.remaining_amount||0)<=0||item.status==='paid')return false;const due=new Date(String(item.due_date).slice(0,10)+'T00:00:00');const today=new Date();today.setHours(0,0,0,0);return due<today},daysOverdue(item){if(!this.isOverdue(item))return 0;const due=new Date(String(item.due_date).slice(0,10)+'T00:00:00');const today=new Date();today.setHours(0,0,0,0);return Math.floor((today-due)/86400000)},displayStatus(item){return this.isOverdue(item)?'overdue':item.status},openDocuments(item){this.documentEntity=item;this.documentsDialog=true},async load(){this.loading=true;try{const r=await api.get('/installments',{params:{status:this.status,from:this.from,to:this.to,per_page:100}});this.items=r.data.data||[]}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to load installments.')}finally{this.loading=false}},openPayment(item){this.selected=item;this.payment={amount:item.remaining_amount,payment_method:'cash',payment_date:new Date().toISOString().slice(0,10),reference_number:'',bank_name:'',cheque_number:'',notes:''};this.paymentDialog=true},async savePayment(){const amount=Number(this.payment.amount);const max=Number(this.selected.remaining_amount);if(!amount||amount<=0||amount>max){this.$root.$emit('show-error','Enter an amount between 0.01 and '+this.money(max)+'.');return}this.saving=true;try{await api.post('/payments',{booking_id:this.selected.booking_id,installment_id:this.selected.id,customer_id:this.selected.booking.customer_id,amount,payment_date:this.payment.payment_date,payment_method:this.payment.payment_method,reference_number:this.payment.reference_number,bank_name:this.payment.bank_name,cheque_number:this.payment.cheque_number,notes:this.payment.notes});this.paymentDialog=false;await this.load();this.$root.$emit('show-success','Installment payment recorded successfully.')}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to record payment.')}finally{this.saving=false}},async view(item){try{const r=await api.get('/installments/'+item.id);this.details=r.data;this.detailsDialog=true}catch(e){this.$root.$emit('show-error','Unable to load installment details.')}},customerName(item){return item&&item.booking&&item.booking.customer&&item.booking.customer.name?item.booking.customer.name:'—'},bookingNumber(item){return item&&item.booking&&item.booking.booking_number?item.booking.booking_number:'—'},planName(item){return item&&item.plan&&item.plan.plan_name?item.plan.plan_name:'—'},money(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))},statusColor(s){return s==='overdue'?'error':s==='paid'?'success':'orange'}}}
</script>
<style scoped>.page{width:100%}.hero{border-left:4px solid #165134}.summary-card,.filter-card,.table-card{border:1px solid rgba(22,81,52,.08);border-radius:15px!important}.summary-card{cursor:pointer;transition:.2s}.summary-card:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(20,50,35,.08)!important}.page ::v-deep .v-data-table__wrapper{overflow-x:auto}</style>
